namespace Astronomy.MediaFactory.Core.KnowledgeFoundation.Integration;
public sealed record AstronomyKnowledgeFoundationCompatibilityIssue(string Code,string Path,string Message);
public sealed class AstronomyKnowledgeFoundationCompatibilityReport{ public AstronomyKnowledgeFoundationCompatibilityReport(IEnumerable<AstronomyKnowledgeFoundationCompatibilityIssue> issues){ArgumentNullException.ThrowIfNull(issues); Issues=Array.AsReadOnly(issues.Select(i=>i??throw new ArgumentException("Issues cannot contain null.",nameof(issues))).OrderBy(i=>i.Path,StringComparer.Ordinal).ThenBy(i=>i.Code,StringComparer.Ordinal).ToArray());} public bool IsCompatible=>Issues.Count==0; public IReadOnlyList<AstronomyKnowledgeFoundationCompatibilityIssue> Issues{get;} public static AstronomyKnowledgeFoundationCompatibilityReport Compatible{get;}=new([]);}
